/** Maps the declarative tree `remote` config onto the canonical remote engine. */
function useTreeRemoteItems<T>(remote: RemoteConfigTree<T> | undefined, open: boolean) {
  return useRemoteItems<T>(
    remote ? (signal) => remote.optionsFn(signal) : undefined,
    remote ? remote.identifier : null,
    {
      enabled: Boolean(remote) && (open || remote?.disableLazyFetch === true),
      refreshOnOpen: remote?.refreshOnOpen === true,
    },
  );
}

export function ComboboxTree<T>({
  value: controlledValue,
  onChange,
  data: dataProp,
  remote,
  menuItemConfig,
  selectedItemConfig,
  flatParentKey,
  rootParentValues,
  multiple,
  multipleConfig,
  placeholder: placeholderProp,
  searchPlaceholder: searchPlaceholderProp,
  emptyMessage: emptyMessageProp,
  loadingMessage: loadingMessageProp,
  remoteErrorMessage: remoteErrorMessageProp,
  label: labelProp,
  disabled,
  fullWidth,
  error,
  required,
  expandAllLabel: expandAllLabelProp,
  collapseAllLabel: collapseAllLabelProp,
  className,
  onBlur,
  onMaxSelectionReached,
}: ComboboxTreeProps<T>) {
  const placeholder = placeholderProp ?? DEFAULT_PLACEHOLDER;
  const searchPlaceholder = searchPlaceholderProp ?? DEFAULT_SEARCH_PLACEHOLDER;
  const emptyMessage = emptyMessageProp ?? DEFAULT_EMPTY_MESSAGE;
  const loadingMessage = loadingMessageProp ?? DEFAULT_LOADING_MESSAGE;
  const remoteErrorMessage = remoteErrorMessageProp ?? DEFAULT_REMOTE_ERROR_MESSAGE;
  const expandAllLabel = expandAllLabelProp ?? DEFAULT_EXPAND_ALL_LABEL;
  const collapseAllLabel = collapseAllLabelProp ?? DEFAULT_COLLAPSE_ALL_LABEL;

  const generatedId = useId();
  const [open, setOpen] = useState(false);
  const [internalSingle, setInternalSingle] = useState("");
  const [internalMulti, setInternalMulti] = useState<string[]>([]);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState("");
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [portalContainer, setPortalContainer] = useState<HTMLElement | null>(null);

  const { items: remoteItems, error: remoteError, isLoading } = useTreeRemoteItems(remote, open);

  const data = useMemo(() => {
    if (remote) return remoteItems;
    return dataProp ?? [];
  }, [remote, remoteItems, dataProp]);

  const valueKey = menuItemConfig.value;
  const treeChildrenKey = COMBOBOX_TREE_CHILDREN_KEY as keyof T;
  const treeData = useMemo(() => {
    if (!flatParentKey) return data;
    return buildNestedFromFlat(data, valueKey, flatParentKey, rootParentValues);
  }, [data, valueKey, flatParentKey, rootParentValues]);
  const searchKeys = menuItemConfig.searchProperties ?? menuItemConfig.label;

  const isMulti = multiple === true;
  const isControlled = controlledValue !== undefined;

  const valueSingle = useMemo((): ComboboxValueType<T> | undefined => {
    if (isControlled)
      return Array.isArray(controlledValue) ? undefined : (controlledValue ?? undefined);

    if (internalSingle === "") return undefined;
    const item = getItemByValue(treeData, internalSingle, valueKey, treeChildrenKey);
    return item ? getRawValueFromItem(item, valueKey) : undefined;
  }, [isControlled, controlledValue, internalSingle, treeData, valueKey, treeChildrenKey]);

  const valueMulti = useMemo((): ComboboxValueType<T>[] => {
    if (isControlled) return Array.isArray(controlledValue) ? controlledValue : [];

    const items = getItemsByValues(treeData, internalMulti, valueKey, treeChildrenKey);
    return items.map((i) => getRawValueFromItem(i, valueKey));
  }, [isControlled, controlledValue, internalMulti, treeData, valueKey, treeChildrenKey]);

  const selectedIds = useMemo(() => {
    const ids = isMulti ? valueMulti.map(String) : valueSingle != null ? [String(valueSingle)] : [];
    return new Set(ids);
  }, [isMulti, valueSingle, valueMulti]);

  const itemMap = useMemo(
    () => buildItemMap(treeData, valueKey, treeChildrenKey),
    [treeData, valueKey, treeChildrenKey],
  );
  const { filteredData, searchExpandedIds } = useMemo(
    () => filterTree(treeData, searchQuery, valueKey, treeChildrenKey, searchKeys),
    [treeData, searchQuery, valueKey, treeChildrenKey, searchKeys],
  );

  const expandedIdsForRender = useMemo(
    () => (searchQuery.trim() ? new Set([...expandedIds, ...searchExpandedIds]) : expandedIds),
    [expandedIds, searchQuery, searchExpandedIds],
  );

  const selectedItems = useMemo(
    () =>
      isMulti
        ? getItemsByValues(treeData, valueMulti.map(String), valueKey, treeChildrenKey)
        : valueSingle != null
          ? ([getItemByValue(treeData, String(valueSingle), valueKey, treeChildrenKey)].filter(
              Boolean,
            ) as T[])
          : [],
    [treeData, isMulti, valueSingle, valueMulti, valueKey, treeChildrenKey],
  );

  const handleSelect = useCallback(
    (id: string) => {
      if (!isMulti) {
        if (!isControlled) setInternalSingle(id);
        const item = getItemByValue(treeData, id, valueKey, treeChildrenKey);
        const rawValue = item != null ? getRawValueFromItem(item, valueKey) : null;
        onChange?.(rawValue, item ? [item] : []);
        setOpen(false);
      }
    },
    [treeData, isControlled, isMulti, onChange, valueKey, treeChildrenKey],
  );

  const handleCheckChange = useCallback(
    (id: string, checked: boolean) => {
      if (!isMulti) return;
      const maxSelection = multipleConfig?.maxSelection;
      const current = valueMulti.map(String);
      const item = itemMap.get(id);
      const idsToApply = item ? getSelfAndDescendantValues(item, valueKey, treeChildrenKey) : [id];
      if (checked) {
        const toAdd = idsToApply.filter((x) => !current.includes(x));
        if (maxSelection != null && current.length + toAdd.length > maxSelection) {
          onMaxSelectionReached?.();
          return;
        }
      }
      const toRemove = new Set(idsToApply);
      const next = checked
        ? [...new Set([...current, ...idsToApply])]
        : current.filter((v) => !toRemove.has(v));
      if (!isControlled) setInternalMulti(next);
      const items = getItemsByValues(treeData, next, valueKey, treeChildrenKey);
      const typedNext = items.map((i) => getRawValueFromItem(i, valueKey));
      onChange?.(typedNext, items);
    },
    [
      treeData,
      isControlled,
      isMulti,
      itemMap,
      multipleConfig?.maxSelection,
      onChange,
      onMaxSelectionReached,
      valueKey,
      treeChildrenKey,
      valueMulti,
    ],
  );

  const handleOpenChange = (isOpen: boolean) => {
    if (isOpen) {
      setPortalContainer(
        triggerRef.current?.closest<HTMLElement>(
          '[data-slot="dialog-content"], [data-slot="sheet-content"]',
        ) ?? null,
      );
    }
    setOpen(isOpen);
    if (!isOpen) {
      setSearchQuery("");
      onBlur?.();
    }
  };

  const allFolderValues = useMemo(
    () => getAllFolderValues(treeData, valueKey, treeChildrenKey),
    [treeData, valueKey, treeChildrenKey],
  );

  const isAllExpanded =
    allFolderValues.length > 0 && expandedIdsForRender.size >= allFolderValues.length;
  const toggleExpandCollapse = () => {
    setExpandedIds(isAllExpanded ? new Set() : new Set(allFolderValues));
  };

  const handleToggleExpand = useCallback((nodeId: string, isOpen: boolean) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (isOpen) next.add(nodeId);
      else next.delete(nodeId);
      return next;
    });
  }, []);

  const buttonContent = useMemo<ReactNode>(() => {
    if (selectedItems.length === 0) return placeholder;
    if (selectedItems.length === 1) {
      const item = selectedItems[0];
      return item ? getButtonLabelNode(item, menuItemConfig, selectedItemConfig) : placeholder;
    }
    const maxVisible = multipleConfig?.maxVisibleItems;
    const toShow = maxVisible ? selectedItems.slice(0, maxVisible) : selectedItems;
    const overflow =
      maxVisible && selectedItems.length > maxVisible ? selectedItems.length - maxVisible : 0;
    const itemsSeparator = selectedItemConfig?.multipleSeparator;
    return (
      <span className={cn("flex items-center flex-wrap", !itemsSeparator && "gap-1")}>
        {toShow.map((item, index) => (
          <span key={getValueFromItem(item, valueKey)} className='flex items-center'>
            {index > 0 && itemsSeparator != null && (
              <span className='mx-1 text-muted-foreground'>{itemsSeparator}</span>
            )}
            <span className='truncate max-w-28'>
              {getButtonLabelNode(item, menuItemConfig, selectedItemConfig)}
            </span>
          </span>
        ))}
        {overflow > 0 && <span className='text-muted-foreground ml-1'>+{overflow}</span>}
      </span>
    );
  }, [
    placeholder,
    selectedItems,
    multipleConfig?.maxVisibleItems,
    menuItemConfig,
    selectedItemConfig,
    valueKey,
  ]);

  return (
    <Fragment>
      {labelProp && (
        <Label htmlFor={generatedId} className='flex items-center gap-2'>
          {labelProp}
          {required && <span className='text-destructive'>*</span>}
        </Label>
      )}
      <Popover open={open} onOpenChange={handleOpenChange}>
        <PopoverTrigger asChild>
          <Button
            ref={triggerRef}
            type='button'
            id={generatedId}
            variant='outline'
            role='combobox'
            aria-expanded={open}
            aria-invalid={error ? true : undefined}
            disabled={disabled || isLoading}
            aria-busy={isLoading || undefined}
            className={cn(
              "justify-between select-none h-9 min-h-9 max-h-9",
              fullWidth ? "w-full" : "min-w-70 w-max",
              error && "text-destructive! border-destructive!",
              className,
            )}
          >
            {buttonContent}
            {isLoading ? (
              <Loader2 className='ml-2 h-4 w-4 shrink-0 animate-spin' />
            ) : (
              <ChevronsUpDown className='ml-2 h-4 w-4 shrink-0 opacity-50' />
            )}
          </Button>
        </PopoverTrigger>
        <ComboboxPopoverContent
          container={portalContainer}
          className="p-0 w-(--radix-popover-trigger-width)"
          align='start'
        >
          <div className='flex flex-col gap-2 p-2 border-b'>
            <div className='flex items-center gap-2'>
              <InputGroup className='flex-1 min-w-0'>
                <InputGroupInput
                  type='text'
                  placeholder={searchPlaceholder}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                <InputGroupAddon align='inline-start'>
                  <Search />
                </InputGroupAddon>
                <InputGroupAddon align='inline-end' className='h-9 w-9 shrink-0'>
                  {allFolderValues.length > 0 && (
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <Button
                          type='button'
                          variant='link'
                          size='icon'
                          className=' text-muted-foreground'
                          onClick={toggleExpandCollapse}
                          aria-label={isAllExpanded ? collapseAllLabel : expandAllLabel}
                        >
                          {isAllExpanded ? (
                            <ListChevronsDownUp className='h-4 w-4' />
                          ) : (
                            <ListChevronsUpDown className='h-4 w-4' />
                          )}
                        </Button>
                      </TooltipTrigger>
                      <TooltipContent>
                        {isAllExpanded ? collapseAllLabel : expandAllLabel}
                      </TooltipContent>
                    </Tooltip>
                  )}
                </InputGroupAddon>
              </InputGroup>
            </div>
          </div>
          <ScrollArea
            type='scroll'
            className='min-h-0 max-h-80 shrink-0 overflow-auto overscroll-contain'
            onWheel={(event) => event.stopPropagation()}
          >
            <TreeContent
              data={filteredData}
              itemMap={itemMap}
              expandedIds={expandedIdsForRender}
              onToggleExpand={handleToggleExpand}
              selectedIds={selectedIds}
              onSelect={handleSelect}
              multiple={isMulti}
              onCheckChange={isMulti ? handleCheckChange : undefined}
              emptyMessage={
                isLoading ? loadingMessage : remoteError ? remoteErrorMessage : emptyMessage
              }
              isLoading={isLoading}
              loadingMessage={loadingMessage}
              menuItemConfig={menuItemConfig}
              valueKey={valueKey}
              childrenKey={treeChildrenKey}
            />
          </ScrollArea>
        </ComboboxPopoverContent>
      </Popover>
    </Fragment>
  );
}

import { buildSearchableValue, getValueFromItem } from "./utils";

/** Warnings fire in dev builds only; works in Vite, Next and union apps (no `process` dependency). */
function getIsDevelopment(): boolean {
  const env = (import.meta as { env?: { DEV?: boolean; NODE_ENV?: string } }).env;
  return env?.DEV === true || env?.NODE_ENV === "development";
}
const isDevelopment = getIsDevelopment();

/** Internal synthetic children key after `buildNestedFromFlat` (not part of flat row shape). */
export const COMBOBOX_TREE_CHILDREN_KEY = "children";

function isRootParentString(parentStr: string, rootExtra: ReadonlySet<string>): boolean {
  return parentStr === "" || rootExtra.has(parentStr);
}

/** Walks flat parent links upward from `startId`; returns true if `childId` is reached (cycle / child is ancestor of proposed parent). */
function flatParentChainReaches<T>(
  itemsById: Map<string, T>,
  startId: string,
  childId: string,
  parentKey: keyof T,
  rootExtra: ReadonlySet<string>,
): boolean {
  let cur = startId;
  const visited = new Set<string>();
  while (true) {
    if (cur === childId) return true;
    if (visited.has(cur)) return true;
    visited.add(cur);
    const node = itemsById.get(cur);
    if (!node) return false;
    const p = getValueFromItem(node, parentKey);
    if (isRootParentString(p, rootExtra)) return false;
    cur = p;
  }
}

/**
 * Builds a nested tree from a flat list using `flatParentKey`. Ignores any existing `children` on rows.
 * Rows are shallow-copied with synthetic `children` arrays. `valueKey` values must be unique.
 * Roots and siblings keep the order rows first appear in `flat` (Map insertion order).
 */
export function buildNestedFromFlat<T>(
  flat: T[],
  valueKey: keyof T,
  flatParentKey: keyof T,
  rootParentValues?: readonly string[],
): T[] {
  const childrenKey = COMBOBOX_TREE_CHILDREN_KEY as keyof T;
  const rootExtra = new Set((rootParentValues ?? []).map(String));
  const itemsById = new Map<string, T>();
  let duplicateWarned = false;

  for (const item of flat) {
    const id = getValueFromItem(item, valueKey);
    if (itemsById.has(id)) {
      if (isDevelopment && !duplicateWarned) {
        console.warn(
          "[ComboboxTree] Duplicate valueKey in flat data; later rows are skipped.",
        );
        duplicateWarned = true;
      }
      continue;
    }
    itemsById.set(id, item);
  }

  type Node = T & Record<string, unknown>;

  const nodes = new Map<string, Node>();
  for (const id of itemsById.keys()) {
    const item = itemsById.get(id)!;
    const shell = { ...item } as Record<string, unknown>;
    shell[String(childrenKey)] = [] as Node[];
    nodes.set(id, shell as Node);
  }

  let orphanWarned = false;

  const effectiveParentId = (id: string): string | null => {
    const item = itemsById.get(id);
    if (!item) return null;
    const parentStr = getValueFromItem(item, flatParentKey);
    if (isRootParentString(parentStr, rootExtra)) return null;
    if (parentStr === id) {
      if (isDevelopment && !orphanWarned) {
        console.warn("[ComboboxTree] flat tree: self-parent row promoted to root.", id);
        orphanWarned = true;
      }
      return null;
    }
    if (!itemsById.has(parentStr)) {
      if (isDevelopment && !orphanWarned) {
        console.warn("[ComboboxTree] flat tree: missing parent; row promoted to root.", id);
        orphanWarned = true;
      }
      return null;
    }
    if (flatParentChainReaches(itemsById, parentStr, id, flatParentKey, rootExtra)) {
      if (isDevelopment && !orphanWarned) {
        console.warn("[ComboboxTree] flat tree: cycle prevented; row promoted to root.", id);
        orphanWarned = true;
      }
      return null;
    }
    return parentStr;
  };

  const rootIds: string[] = [];
  for (const id of itemsById.keys()) {
    if (effectiveParentId(id) === null) rootIds.push(id);
  }

  for (const id of itemsById.keys()) {
    const pid = effectiveParentId(id);
    if (pid === null) continue;
    const parentNode = nodes.get(pid);
    const childNode = nodes.get(id);
    if (parentNode && childNode) {
      (parentNode[childrenKey as string] as Node[]).push(childNode);
    }
  }

  // Sibling and root order follow `flat` / Map insertion order (no re-sort).
  const roots = rootIds.map((rid) => nodes.get(rid)!).filter(Boolean);
  return roots as T[];
}

export function getChildren<T>(item: T, childrenKey: keyof T): T[] | undefined {
  const children = (item as Record<keyof T, unknown>)[childrenKey];
  return Array.isArray(children) ? (children as T[]) : undefined;
}

export function getItemByValue<T>(
  items: T[],
  value: string,
  valueKey: keyof T,
  childrenKey: keyof T,
): T | null {
  for (const item of items) {
    if (getValueFromItem(item, valueKey) === value) return item;
    const children = getChildren(item, childrenKey);
    if (children?.length) {
      const found = getItemByValue(children, value, valueKey, childrenKey);
      if (found) return found;
    }
  }
  return null;
}

export function getItemsByValues<T>(
  items: T[],
  values: string[],
  valueKey: keyof T,
  childrenKey: keyof T,
): T[] {
  const result: T[] = [];
  for (const v of values) {
    const item = getItemByValue(items, v, valueKey, childrenKey);
    if (item) result.push(item);
  }
  return result;
}

export function buildItemMap<T>(
  items: T[],
  valueKey: keyof T,
  childrenKey: keyof T,
): Map<string, T> {
  const map = new Map<string, T>();
  const processItem = (item: T) => {
    map.set(getValueFromItem(item, valueKey), item);
    getChildren(item, childrenKey)?.forEach(processItem);
  };
  items.forEach(processItem);
  return map;
}

export function getAllFolderValues<T>(
  items: T[],
  valueKey: keyof T,
  childrenKey: keyof T,
): string[] {
  let ids: string[] = [];
  items.forEach((item) => {
    const children = getChildren(item, childrenKey);
    if (children?.length) {
      ids.push(getValueFromItem(item, valueKey));
      ids = [...ids, ...getAllFolderValues(children, valueKey, childrenKey)];
    }
  });
  return ids;
}

export function getSelfAndDescendantValues<T>(
  item: T,
  valueKey: keyof T,
  childrenKey: keyof T,
): string[] {
  const ids = [getValueFromItem(item, valueKey)];
  getChildren(item, childrenKey)?.forEach((child) => {
    ids.push(...getSelfAndDescendantValues(child, valueKey, childrenKey));
  });
  return ids;
}

export function getCheckState<T>(
  item: T,
  itemMap: Map<string, T>,
  selectedIds: Set<string>,
  valueKey: keyof T,
  childrenKey: keyof T,
): "checked" | "unchecked" | "indeterminate" {
  const itemValue = getValueFromItem(item, valueKey);
  const originalItem = itemMap.get(itemValue);
  if (!originalItem) return "unchecked";

  const children = getChildren(originalItem, childrenKey);
  if (!children?.length) {
    return selectedIds.has(itemValue) ? "checked" : "unchecked";
  }

  let checkedCount = 0;
  let indeterminateCount = 0;
  children.forEach((child) => {
    const childState = getCheckState(child, itemMap, selectedIds, valueKey, childrenKey);
    if (childState === "checked") checkedCount++;
    if (childState === "indeterminate") indeterminateCount++;
  });
  const total = children.length;
  if (checkedCount === total) return "checked";
  if (checkedCount > 0 || indeterminateCount > 0) return "indeterminate";
  return "unchecked";
}

export function filterTree<T>(
  items: T[],
  searchQuery: string,
  valueKey: keyof T,
  childrenKey: keyof T,
  searchKeys: (keyof T)[],
): { filteredData: T[]; searchExpandedIds: Set<string> } {
  if (!searchQuery.trim()) {
    return { filteredData: items, searchExpandedIds: new Set<string>() };
  }
  const searchLower = searchQuery.toLowerCase();
  const newExpandedIds = new Set<string>();

  const itemMatches = (item: T): boolean => {
    const searchable = buildSearchableValue(item, searchKeys);
    if (searchable.includes(searchLower)) return true;
    return getChildren(item, childrenKey)?.some(itemMatches) ?? false;
  };

  const filter = (list: T[]): T[] =>
    list
      .map((item) => {
        const children = getChildren(item, childrenKey);
        if (!children?.length) return itemMatches(item) ? item : null;
        const filteredChildren = filter(children);
        if (filteredChildren.length > 0 || itemMatches(item)) {
          newExpandedIds.add(getValueFromItem(item, valueKey));
          return { ...item, [childrenKey]: filteredChildren } as T;
        }
        return null;
      })
      .filter((x): x is T => x !== null);

  return { filteredData: filter(items), searchExpandedIds: newExpandedIds };
}

"use client";

import { getLabelNode, getValueFromItem } from "./utils";
import type { MenuItemConfig } from "./types";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { cn } from "@/lib/utils";
import { ChevronRight, Loader2 } from "lucide-react";
import { Fragment, useMemo } from "react";
import { getCheckState, getChildren } from "./tree-utils";

export interface TreeContentProps<T> {
  data: T[];
  itemMap: Map<string, T>;
  expandedIds: Set<string>;
  onToggleExpand: (id: string, isOpen: boolean) => void;
  selectedIds: Set<string>;
  onSelect: (id: string) => void;
  multiple?: boolean;
  onCheckChange?: (id: string, checked: boolean) => void;
  emptyMessage: string;
  isLoading?: boolean;
  loadingMessage?: string;
  menuItemConfig: MenuItemConfig<T>;
  valueKey: keyof T;
  childrenKey: keyof T;
}

interface TreeItemProps<T> {
  item: T;
  depth: number;
  expandedIds: Set<string>;
  onToggleExpand: (id: string, isOpen: boolean) => void;
  selectedIds: Set<string>;
  onSelect: (id: string) => void;
  multiple?: boolean;
  onCheckChange?: (id: string, checked: boolean) => void;
  itemMap: Map<string, T>;
  menuItemConfig: MenuItemConfig<T>;
  valueKey: keyof T;
  childrenKey: keyof T;
}

function TreeItem<T>({
  item,
  depth,
  expandedIds,
  onToggleExpand,
  selectedIds,
  onSelect,
  multiple,
  onCheckChange,
  itemMap,
  menuItemConfig,
  valueKey,
  childrenKey,
}: TreeItemProps<T>) {
  const itemValue = getValueFromItem(item, valueKey);
  const isOpen = expandedIds.has(itemValue);
  const children = getChildren(item, childrenKey);
  const isSelectable = !menuItemConfig.isOptionDisabled?.(item);

  const checkState = useMemo(
    () => (multiple ? getCheckState(item, itemMap, selectedIds, valueKey, childrenKey) : null),
    [item, itemMap, multiple, selectedIds, valueKey, childrenKey],
  );

  const hasChildren = (children?.length ?? 0) > 0;

  const handleRowClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (
      (e.target as HTMLElement).closest("button") ||
      (e.target as HTMLElement).closest("[role='checkbox']")
    )
      return;
    if (!isSelectable) {
      if (hasChildren) onToggleExpand(itemValue, !isOpen);
      return;
    }
    if (multiple) {
      const newChecked = checkState !== "checked";
      onCheckChange?.(itemValue, newChecked);
    } else {
      onSelect(itemValue);
    }
  };

  const rowContent = (
    <div className='flex items-center gap-2 flex-1 min-w-0'>
      {hasChildren ? (
        <Fragment>
          <Collapsible open={isOpen} onOpenChange={(open) => onToggleExpand(itemValue, open)}>
            <CollapsibleTrigger asChild onClick={(e) => e.stopPropagation()}>
              <Button type='button' variant='ghost' size='icon' className='h-6 w-6 shrink-0'>
                <ChevronRight
                  className={cn("h-4 w-4 transition-transform", isOpen && "rotate-90")}
                />
              </Button>
            </CollapsibleTrigger>
          </Collapsible>
          {multiple && isSelectable && (
            <div onClick={(e) => e.stopPropagation()} className='shrink-0'>
              <Checkbox
                checked={
                  checkState === "checked"
                    ? true
                    : checkState === "indeterminate"
                      ? "indeterminate"
                      : false
                }
                onCheckedChange={(checked) => onCheckChange?.(itemValue, checked === true)}
              />
            </div>
          )}
        </Fragment>
      ) : (
        <span className='w-6 shrink-0' />
      )}
      {!hasChildren && multiple && isSelectable && (
        <div onClick={(e) => e.stopPropagation()} className='shrink-0'>
          <Checkbox
            checked={selectedIds.has(itemValue)}
            onCheckedChange={(checked) => onCheckChange?.(itemValue, checked === true)}
          />
        </div>
      )}
      {menuItemConfig.customStartNode && (
        <span className='shrink-0'>{menuItemConfig.customStartNode(item)}</span>
      )}
      <span className='truncate text-sm font-normal'>{getLabelNode(item, menuItemConfig)}</span>
    </div>
  );

  return (
    <div className='flex flex-col'>
      <div
        data-tree-item
        data-id={itemValue}
        data-depth={depth}
        className={cn("select-none cursor-pointer rounded px-1 flex items-center h-8")}
        style={{ paddingLeft: `${depth * 20 + 4}px` }}
        onClick={handleRowClick}
      >
        {rowContent}
      </div>
      {hasChildren ? (
        <Collapsible open={isOpen} onOpenChange={(open) => onToggleExpand(itemValue, open)}>
          <CollapsibleContent>
            {children!.map((child) => (
              <TreeItem
                key={getValueFromItem(child, valueKey)}
                item={child}
                depth={depth + 1}
                expandedIds={expandedIds}
                onToggleExpand={onToggleExpand}
                selectedIds={selectedIds}
                onSelect={onSelect}
                multiple={multiple}
                onCheckChange={onCheckChange}
                itemMap={itemMap}
                menuItemConfig={menuItemConfig}
                valueKey={valueKey}
                childrenKey={childrenKey}
              />
            ))}
          </CollapsibleContent>
        </Collapsible>
      ) : null}
    </div>
  );
}

export function TreeContent<T>({
  data,
  itemMap,
  expandedIds,
  onToggleExpand,
  selectedIds,
  onSelect,
  multiple,
  onCheckChange,
  emptyMessage,
  isLoading,
  loadingMessage,
  menuItemConfig,
  valueKey,
  childrenKey,
}: TreeContentProps<T>) {
  if (data.length === 0) {
    const message = isLoading && loadingMessage ? loadingMessage : emptyMessage;
    return (
      <div
        className='flex items-center justify-center gap-2 px-3 py-6 text-sm text-muted-foreground'
        role={isLoading ? "status" : undefined}
      >
        {isLoading ? <Loader2 className='h-4 w-4 animate-spin' /> : null}
        <span>{message}</span>
      </div>
    );
  }
  return (
    <div className='py-1'>
      {data.map((item) => (
        <TreeItem
          key={getValueFromItem(item, valueKey)}
          item={item}
          depth={0}
          expandedIds={expandedIds}
          onToggleExpand={onToggleExpand}
          selectedIds={selectedIds}
          onSelect={onSelect}
          multiple={multiple}
          onCheckChange={onCheckChange}
          itemMap={itemMap}
          menuItemConfig={menuItemConfig}
          valueKey={valueKey}
          childrenKey={childrenKey}
        />
      ))}
    </div>
  );
}
